/* =====================================================================================================
   MANUAL SQL UPGRADE SCRIPT
   Migration: 202609090519337_AgentCostTables
   Predecessor: 202608310800001_ColumnstoreUsageReportMetrics
   =====================================================================================================
   For operators / DBAs who upgrade the Analytics database schema BY HAND instead of running the installer
   (which applies EF migrations automatically). It performs the same schema changes as the migration and
   then stamps __MigrationHistory so EF (DatabaseUpgrader / MigrateDatabaseToLatestVersion) and the web
   app Health page recognise it as applied.

   WHAT IT DOES
     Creates four NEW, EMPTY tables for the optional agent-cost imports, plus their two unique indexes:

       * copilot_studio_credit_daily     billed Copilot Studio consumption (Copilot Credits), one row per
                                         usage day x environment x agent x billing dimension
       * copilot_studio_credit_capacity  daily snapshot of the tenant's whole Copilot Credits entitlement
       * azure_cost_daily                daily Azure spend from Microsoft Cost Management
       * agent_cost_import_log           per-run diagnostics for the two imports above

   CLASSIFICATION: PURELY ADDITIVE
     Nothing existing is altered, dropped or rewritten. No existing table is touched, no existing column
     changes type, and no existing query changes plan - so there is no "before" state to measure and this
     migration carries no performance benchmark by design.

   HOW LONG IT TAKES / DOWNTIME
     Seconds, on a tenant of any size. Creating empty tables is independent of how much data you already
     hold, and the only locks taken are on tables that do not yet exist. NO MAINTENANCE WINDOW IS NEEDED
     and the importer does not have to be stopped.

   ABOUT THE TWO UNIQUE INDEXES
     They are not an optimisation - they are the upsert keys. Both cost sources restate history (Azure
     re-estimates an open billing period several times a day; Copilot Studio recalculates consumption as
     usage days settle), so both importers deliberately re-read a trailing window on every run. Without
     these indexes a re-read would duplicate every restated day instead of correcting it.

   AFTER RUNNING THIS
     The tables stay empty until the corresponding import is switched on in the installer AND the runtime
     service principal has been granted the extra permission each one needs:
       * Copilot Studio credits - a Power Platform RBAC role (e.g. "Power Platform reader") assigned to
         the service principal at tenant scope. Note that Microsoft has not confirmed application-only
         access to the licensing entitlement routes, so this import may report an authorisation failure
         on some tenants even when the role is correctly assigned.
       * Azure costs - the "Cost Management Reader" role on each scope, plus the AzureCostScopes App
         Service application setting naming those scopes.
     Check dbo.agent_cost_import_log after the first import cycle: it distinguishes "nothing to import"
     from "the API refused us", which are otherwise indistinguishable.

   IDEMPOTENT
     Every step is guarded, so running this script twice is safe and the second run is a no-op.

   RUN ORDER
     The manual scripts form a strict prerequisite chain. Run them in migration-id order. This script
     requires 202608310800001_ColumnstoreUsageReportMetrics to be stamped first and will refuse
     to stamp itself (with an error) if it is not.
   ===================================================================================================== */

SET NOCOUNT ON;

/* QUOTED_IDENTIFIER must be ON for the xs:base64Binary() call that rebuilds the model blob further
   down. SSMS connects with it ON, but sqlcmd defaults it OFF, so without this the stamp fails with
   "INSERT failed because the following SET options have incorrect settings: 'QUOTED_IDENTIFIER'" -
   after the schema work has already succeeded, leaving the migration unstamped and blocking the next
   script in the chain. */
SET QUOTED_IDENTIFIER ON;
GO

DECLARE @migration nvarchar(200) = N'202609090519337_AgentCostTables';
DECLARE @msg nvarchar(500);
DECLARE @start datetime2 = SYSUTCDATETIME();

SET @msg = @migration + N': starting.';
RAISERROR(@msg, 0, 1) WITH NOWAIT;

/* ---------------------------------------------------------------------------------------------------
   1. dbo.agent_cost_import_log
   --------------------------------------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.agent_cost_import_log', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.agent_cost_import_log (
        [id]            int             IDENTITY(1, 1) NOT NULL,
        [import_name]   nvarchar(100)   NULL,
        [imported_utc]  datetime        NOT NULL,
        [window_from]   datetime        NULL,
        [window_to]     datetime        NULL,
        [rows_read]     int             NOT NULL,
        [rows_saved]    int             NOT NULL,
        [error]         nvarchar(1000)  NULL,
        CONSTRAINT [PK_dbo.agent_cost_import_log] PRIMARY KEY CLUSTERED ([id] ASC)
    );
    RAISERROR('AgentCostTables: created dbo.agent_cost_import_log.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('AgentCostTables: dbo.agent_cost_import_log already exists.', 0, 1) WITH NOWAIT;
GO

/* ---------------------------------------------------------------------------------------------------
   2. dbo.azure_cost_daily

   Every text column is nvarchar: meter, service and resource names come from a customer tenant and can
   contain non-Latin characters, which varchar would silently corrupt. resource_id is nvarchar(850)
   because that is the widest Unicode string SQL Server can carry in an index key (1700 bytes / 2).
   --------------------------------------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.azure_cost_daily', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.azure_cost_daily (
        [id]                 int             IDENTITY(1, 1) NOT NULL,
        [usage_date]         datetime        NOT NULL,
        [scope]              nvarchar(400)   NULL,
        [subscription_id]    nvarchar(100)   NULL,
        [resource_id]        nvarchar(850)   NULL,
        [resource_group]     nvarchar(255)   NULL,
        [service_name]       nvarchar(255)   NULL,
        [meter_category]     nvarchar(255)   NULL,
        [meter_sub_category] nvarchar(255)   NULL,
        [meter_name]         nvarchar(255)   NULL,
        [cost]               decimal(18, 6)  NOT NULL,
        [currency]           nvarchar(10)    NULL,
        [quantity]           decimal(18, 6)  NULL,
        [is_estimated]       bit             NOT NULL,
        [row_hash]           nvarchar(64)    NOT NULL,
        [imported_utc]       datetime        NOT NULL,
        CONSTRAINT [PK_dbo.azure_cost_daily] PRIMARY KEY CLUSTERED ([id] ASC)
    );
    RAISERROR('AgentCostTables: created dbo.azure_cost_daily.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('AgentCostTables: dbo.azure_cost_daily already exists.', 0, 1) WITH NOWAIT;
GO

IF OBJECT_ID(N'dbo.azure_cost_daily', N'U') IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM sys.indexes
                   WHERE object_id = OBJECT_ID(N'dbo.azure_cost_daily')
                     AND name = N'IX_usage_date_row_hash')
BEGIN
    CREATE UNIQUE INDEX [IX_usage_date_row_hash]
        ON dbo.azure_cost_daily ([usage_date] ASC, [row_hash] ASC);
    RAISERROR('AgentCostTables: created IX_usage_date_row_hash on dbo.azure_cost_daily.', 0, 1) WITH NOWAIT;
END
GO

/* ---------------------------------------------------------------------------------------------------
   3. dbo.copilot_studio_credit_capacity
   --------------------------------------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.copilot_studio_credit_capacity', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.copilot_studio_credit_capacity (
        [id]                     int             IDENTITY(1, 1) NOT NULL,
        [snapshot_utc]           datetime        NOT NULL,
        [consumption_as_of]      datetime        NULL,
        [entitled]               decimal(18, 6)  NULL,
        [consumed]               decimal(18, 6)  NULL,
        [consumption_type]       nvarchar(50)    NULL,
        [allocated]              decimal(18, 6)  NULL,
        [available]              decimal(18, 6)  NULL,
        [pay_as_you_go_consumed] decimal(18, 6)  NULL,
        [status]                 nvarchar(50)    NULL,
        CONSTRAINT [PK_dbo.copilot_studio_credit_capacity] PRIMARY KEY CLUSTERED ([id] ASC)
    );
    RAISERROR('AgentCostTables: created dbo.copilot_studio_credit_capacity.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('AgentCostTables: dbo.copilot_studio_credit_capacity already exists.', 0, 1) WITH NOWAIT;
GO

/* ---------------------------------------------------------------------------------------------------
   4. dbo.copilot_studio_credit_daily

   There is deliberately NO user column and no foreign key to copilot_studio_bots. Microsoft bills
   Copilot Studio at the environment and agent level rather than per user, and the licensing API returns
   only a distinct-user COUNT (distinct_users), never identities. The agent id is stored as plain text
   because nothing verifies that it uses the same identifier as the audit feed's bot id.
   --------------------------------------------------------------------------------------------------- */
IF OBJECT_ID(N'dbo.copilot_studio_credit_daily', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.copilot_studio_credit_daily (
        [id]                 int             IDENTITY(1, 1) NOT NULL,
        [usage_date]         datetime        NOT NULL,
        [environment_id]     nvarchar(200)   NULL,
        [environment_name]   nvarchar(255)   NULL,
        [agent_id]           nvarchar(200)   NULL,
        [agent_name]         nvarchar(255)   NULL,
        [harness]            nvarchar(50)    NULL,
        [feature_name]       nvarchar(200)   NULL,
        [channel_id]         nvarchar(200)   NULL,
        [llm_model]          nvarchar(200)   NULL,
        [tool_invoked]       nvarchar(400)   NULL,
        [knowledge_sources]  nvarchar(400)   NULL,
        [billed_credits]     decimal(18, 6)  NOT NULL,
        [non_billed_credits] decimal(18, 6)  NULL,
        [distinct_users]     int             NULL,
        [last_refreshed_utc] datetime        NULL,
        [dimension_hash]     nvarchar(64)    NOT NULL,
        [imported_utc]       datetime        NOT NULL,
        CONSTRAINT [PK_dbo.copilot_studio_credit_daily] PRIMARY KEY CLUSTERED ([id] ASC)
    );
    RAISERROR('AgentCostTables: created dbo.copilot_studio_credit_daily.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('AgentCostTables: dbo.copilot_studio_credit_daily already exists.', 0, 1) WITH NOWAIT;
GO

IF OBJECT_ID(N'dbo.copilot_studio_credit_daily', N'U') IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM sys.indexes
                   WHERE object_id = OBJECT_ID(N'dbo.copilot_studio_credit_daily')
                     AND name = N'IX_usage_date_dimension_hash')
BEGIN
    CREATE UNIQUE INDEX [IX_usage_date_dimension_hash]
        ON dbo.copilot_studio_credit_daily ([usage_date] ASC, [dimension_hash] ASC);
    RAISERROR('AgentCostTables: created IX_usage_date_dimension_hash on dbo.copilot_studio_credit_daily.', 0, 1) WITH NOWAIT;
END
GO

/* =====================================================================================================
   Record the migration so EF (DatabaseUpgrader / MigrateDatabaseToLatestVersion) and the web app Health
   page treat it as applied.

   Unlike the index-only migrations that precede it, this one CHANGES THE EF ENTITY MODEL (it adds four
   entities), so its model snapshot is NOT identical to its predecessor's and the stamp cannot simply
   copy that row. The new snapshot is embedded below as base64 and converted to the varbinary blob EF
   stores.

   The pre-stamp guard checks SCHEMA ONLY - that the four tables exist. It deliberately does not inspect
   any row counts: a data-state guard cannot be satisfied reliably while the importer is running, and
   refusing to stamp on that basis has previously stranded a customer upgrade by blocking the next script
   in the chain.

   Guarded so a re-run is a no-op, and conditional on the predecessor being present so the scripts cannot
   be applied out of order.
   ===================================================================================================== */
IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202609090519337_AgentCostTables')
BEGIN
    IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = N'202608310800001_ColumnstoreUsageReportMetrics')
        RAISERROR('AgentCostTables: prerequisite migration 202608310800001_ColumnstoreUsageReportMetrics is missing from __MigrationHistory, so this was NOT stamped. Run the manual scripts in migration-id order.', 16, 1) WITH NOWAIT;
    ELSE IF OBJECT_ID(N'dbo.copilot_studio_credit_daily', N'U') IS NULL
          OR OBJECT_ID(N'dbo.copilot_studio_credit_capacity', N'U') IS NULL
          OR OBJECT_ID(N'dbo.azure_cost_daily', N'U') IS NULL
          OR OBJECT_ID(N'dbo.agent_cost_import_log', N'U') IS NULL
        RAISERROR('AgentCostTables: NOT stamped - the schema work did not complete (one or more of the four tables is missing). Re-run this script; note that sqlcmd and SSMS continue past a failed batch, so an earlier error may be further up the output.', 16, 1) WITH NOWAIT;
    ELSE
    BEGIN
        DECLARE @model nvarchar(max) = N'';

        INSERT INTO dbo.__MigrationHistory (MigrationId, ContextKey, Model, ProductVersion)
        SELECT TOP 1
            N'202609090519337_AgentCostTables',
            ContextKey,
            CAST(N'' AS xml).value('xs:base64Binary(sql:variable("@model"))', 'varbinary(max)'),
            ProductVersion
        FROM dbo.__MigrationHistory
        WHERE MigrationId = N'202608310800001_ColumnstoreUsageReportMetrics';

        RAISERROR('AgentCostTables: recorded in __MigrationHistory.', 0, 1) WITH NOWAIT;
    END
END
ELSE
    RAISERROR('AgentCostTables: already recorded in __MigrationHistory, nothing to do.', 0, 1) WITH NOWAIT;
GO